function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MajorityChecker' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with MajorityChecker(arr).';
  const arr = args[0][0];
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 20000) return 'arr needs 1 to 20000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 20000)) return 'Each value of arr is between 1 and 20000.';
  if (operations.length - 1 > 10000) return 'At most 10000 calls to query.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'query') return 'Only query can follow the constructor.';
    const call = args[i];
    if (!Array.isArray(call) || call.length !== 3 || !call.every(Number.isInteger)) return 'query takes three integers.';
    const [left, right, threshold] = call;
    if (left < 0 || left > right || right >= arr.length) return 'query needs 0 <= left <= right < arr.length.';
    const length = right - left + 1;
    if (threshold > length || 2 * threshold <= length) return 'threshold must be more than half the slice length and at most its length.';
  }
  return null;
}

