class MajorityChecker {
  constructor(arr) {
    this.size = arr.length;
    this.tree = new Array(4 * this.size);
    this.positions = new Map();
    for (let i = 0; i < arr.length; i++) {
      if (!this.positions.has(arr[i])) {
        this.positions.set(arr[i], []);
      }
      this.positions.get(arr[i]).push(i);
    }
    this.build(arr, 1, 0, this.size - 1);
  }

  merge([firstValue, firstVotes], [secondValue, secondVotes]) {
    if (firstValue === secondValue) {
      return [firstValue, firstVotes + secondVotes];
    }
    return firstVotes >= secondVotes ? [firstValue, firstVotes - secondVotes] : [secondValue, secondVotes - firstVotes];
  }

  build(arr, node, lo, hi) {
    if (lo === hi) {
      this.tree[node] = [arr[lo], 1];
      return;
    }
    const mid = (lo + hi) >> 1;
    this.build(arr, 2 * node, lo, mid);
    this.build(arr, 2 * node + 1, mid + 1, hi);
    this.tree[node] = this.merge(this.tree[2 * node], this.tree[2 * node + 1]);
  }

  candidate(node, lo, hi, left, right) {
    if (right < lo || hi < left) {
      return [0, 0];
    }
    if (left <= lo && hi <= right) {
      return this.tree[node];
    }
    const mid = (lo + hi) >> 1;
    const fromLeft = this.candidate(2 * node, lo, mid, left, right);
    const fromRight = this.candidate(2 * node + 1, mid + 1, hi, left, right);
    return this.merge(fromLeft, fromRight);
  }

  lowerBound(list, target) {
    let lo = 0;
    let hi = list.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (list[mid] < target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  query(left, right, threshold) {
    const [guess] = this.candidate(1, 0, this.size - 1, left, right);
    const list = this.positions.get(guess) || [];
    const hits = this.lowerBound(list, right + 1) - this.lowerBound(list, left);
    return hits >= threshold ? guess : -1;
  }
}

