class MajorityChecker {
  constructor(arr) {
    this.arr = arr.slice();
  }
  query(left, right, threshold) {
    const counts = new Map();
    for (let i = left; i <= right; i++) counts.set(this.arr[i], (counts.get(this.arr[i]) || 0) + 1);
    for (const [value, count] of counts) if (count >= threshold) return value;
    return -1;
  }
}

