function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(1500, 2000) : pick(1, 10);
  const paletteSize = large ? pick(2, 50) : pick(1, 3);
  const palette = Array.from({ length: paletteSize }, () => (large || rand() < 0.2 ? pick(1, 20000) : pick(1, 5)));
  const arr = [];
  // Runs dominated by one value make majorities common.
  while (arr.length < n) {
    const dominant = palette[pick(0, paletteSize - 1)];
    const runLength = pick(1, large ? 400 : 6);
    const share = rand();
    for (let k = 0; k < runLength && arr.length < n; k++) arr.push(rand() < share ? dominant : palette[pick(0, paletteSize - 1)]);
  }
  const queries = large ? 499 : pick(1, 10);
  const operations = ['MajorityChecker'];
  const args = [[arr]];
  for (let q = 0; q < queries; q++) {
    const length = rand() < 0.5 ? pick(1, Math.min(n, 50)) : pick(1, n);
    const left = pick(0, n - length);
    const right = left + length - 1;
    const low = Math.floor(length / 2) + 1;
    // Thresholds lean toward the smallest allowed value so both answers show up.
    const threshold = low + Math.floor(rand() ** 3 * (length - low + 1));
    operations.push('query');
    args.push([left, right, threshold]);
  }
  return [operations, args];
}
